  text-overflow: ellipsis;
  white-space: nowrap;
  margin-top: 3px !important;
}
.gb-view-toggle {
  display: inline-flex;
  background: var(--panel);
  border: 1px solid var(--edge);
  border-radius: 6px;
  padding: 2px;
  gap: 2px;
  flex-shrink: 0;
}
.gb-view-toggle button {
  border: none;
  background: transparent;
  padding: 3px 7px;
  border-radius: 4px;
  font-size: 11px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  line-height: 1;
}
.gb-view-toggle button:hover {
  color: var(--text);
}
.gb-view-toggle button.is-active {
  background: var(--bg);
  color: var(--text);
  font-weight: 500;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}
.gb-message-content {
  margin-top: 14px;
}
.gb-plain-body {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  font-family: inherit;
  font-size: 14px;
  line-height: 1.65;
  color: var(--text);
}
.gb-link-chip {
  display: inline-flex;
  align-items: center;
  vertical-align: middle;
  margin: 1px 3px;
  padding: 2px 7px;
  border-radius: 4px;
  background: var(--panel);
  border: 1px solid var(--edge);
  font-size: 12px;
  line-height: 1.4;
  gap: 5px;
  max-width: 100%;
}
.gb-link-url {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #3b82f6;
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gb-link-url:hover {
  text-decoration: underline;
}
.gb-link-copy-btn {
  border: none;
  background: transparent;
  padding: 2px;
  border-radius: 3px;
  color: var(--muted);
  cursor: pointer;
  display: flex;
  align-items: center;
}
.gb-link-copy-btn:hover {
  color: var(--text);
  background: rgba(127, 127, 127, 0.15);
}
.gb-email-html {
  font-size: 14px;
  line-height: 1.6;
  color: var(--text);
  overflow-x: auto;
  max-width: 100%;
  word-break: break-word;
}
.gb-email-html img {
  max-width: 100% !important;
  height: auto !important;
}
.gb-email-html table {
  max-width: 100% !important;
}
.gb-email-html a {
  color: #3b82f6;
  text-decoration: underline;
  cursor: pointer;
}
.gb-email-html [align="center" i],
.gb-email-html center {
  text-align: -webkit-center;
  text-align: center;
}
.gb-email-html table[align="center" i],
.gb-email-html [align="center" i] table,
.gb-email-html [style*="text-align: center" i] table,
.gb-email-html [style*="text-align:center" i] table,
.gb-email-html center table {
  margin-left: auto;
  margin-right: auto;
}
.gb-email-html [align="center" i] img,
.gb-email-html [style*="text-align: center" i] img,
.gb-email-html [style*="text-align:center" i] img,
.gb-email-html [style*="text-align: -webkit-center" i] img,
.gb-email-html [style*="text-align:-webkit-center" i] img,
.gb-email-html center img,
.gb-email-html img[align="center" i],
.gb-email-html img[align="middle" i] {
  margin-left: auto !important;
  margin-right: auto !important;
}
.gb-truncated {
  margin-top: 8px;
}
.gb-form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.gb-form label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  font-size: 12px;
  min-width: 0;
}
.gb-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.gb-form :is(input, select, textarea) {
  width: 100%;
  min-width: 0;
  padding: 9px 11px;
  border: 1px solid var(--edge);
  border-radius: 7px;
  background: var(--surface);
  font-size: 14px;
}
.gb-form textarea {
  resize: vertical;
  line-height: 1.6;
}
.gb-save {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 40px;
  position: sticky;
  bottom: -24px;
  background: var(--surface);
  padding: 12px 0;
  border-top: 1px solid var(--edge);
}
.gb-save span {
  font-size: 11px;
  color: var(--muted);
}
.gb-app .gb-primary {
  background: var(--action);
  color: var(--on-action);
}
.gb-alert {
  position: absolute;
  right: 20px;
  top: 64px;
  z-index: 4;
  width: min(460px, calc(100% - 40px));
  box-shadow: 0 4px 20px #0002;
  border-radius: 8px;
}
.gb-error {
  max-width: 100%;
  border: 1px solid light-dark(#dfbaba, #704444);
  background: var(--surface);
  padding: 10px 12px;
  border-radius: 8px;
  font-size: 12px;
  overflow: hidden;
}
.gb-detail .gb-error {
  margin-bottom: 12px;
}
.gb-error > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.gb-error > div > strong {
  font-weight: 500;
}
.gb-error button {
  padding: 4px 8px;
  font-size: 12px;
}
.gb-error summary {
  cursor: pointer;
  padding: 5px 0 0;
  color: var(--muted);
}
.gb-error textarea {
  margin-top: 10px;
  width: 100%;
  height: 132px;
  max-height: 160px;
  resize: none;
  font:
    12px/1.6 ui-monospace,
    monospace;
  color: var(--text);
  border: 1px solid var(--edge);
  border-radius: 5px;
  background: var(--panel);
  padding: 8px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.gb-copy-row {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-top: 8px;
}
.gb-copy-row span {
  font-size: 11px;
  color: var(--muted);
}
.gb-spin {
  animation: gb-spin 1.5s linear infinite;
}
@keyframes gb-spin {
  to {
    transform: rotate(360deg);
  }
}
@media (max-width: 740px) {
  .gb-app {
    padding: 12px;
  }
  .gb-header {
    flex-wrap: wrap;
    gap: 10px;
  }
  .gb-brand {
    flex: 1;
    min-width: 0;
  }
  .gb-search {
    order: 4;
    flex: 1 1 100%;
    min-width: 0;
  }
  .gb-account {
    max-width: 190px;
  }
  .gb-workspace {
    grid-template-columns: 280px minmax(320px, 1fr);
    margin-top: 12px;
  }
  .gb-detail-scroll {
    padding: 20px;
  }
  .gb-detail-top {
    padding: 12px 20px 8px;
  }
  .gb-detail-tabs {
    padding: 0 20px;
  }
  .gb-alert {
    right: 12px;
    top: 108px;
    width: calc(100% - 24px);
  }
}
